        }
        if hasSecondary {
            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 6) {
                    ForEach(secondarySurfaces) { surface in
                        secondaryTile(for: surface)
                            .frame(width: tileWidth, height: rowHeight)
                    }
                }

